"use client";

import { type CSSProperties, type ReactNode, useEffect, useMemo, useRef, useState } from "react";
import { useControllableState } from "../hooks";
import { useProximity } from "../interaction/hooks";
import { cx } from "../utils/cx";
import { Checkbox } from "./field";
import { Pagination } from "./pagination";
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "./table";

export type DataTableColumn<T> = {
  id: string;
  header: ReactNode;
  /** The sortable value; also the cell content when `cell` is not given. */
  accessor?: (row: T) => string | number | Date | boolean | null | undefined;
  /** Custom cell content. */
  cell?: (row: T) => ReactNode;
  sortable?: boolean;
  /** Right-aligned tabular figures. */
  numeric?: boolean;
  /** The cell that names the row (rendered as a row header). One per table. */
  rowHeader?: boolean;
};

export type DataTableProps<T> = {
  /** Names the table (its caption, visible to assistive technology). */
  caption: string;
  columns: DataTableColumn<T>[];
  rows: T[];
  /** A stable id for each row (needed for selection). */
  getRowId: (row: T) => string;
  /** Show a checkbox column. */
  selectable?: boolean;
  selected?: string[];
  defaultSelected?: string[];
  onSelectedChange?: (ids: string[]) => void;
  /** Rows per page; omit to show every row. */
  pageSize?: number;
  /** Initial sort: a column id and direction. */
  defaultSort?: { id: string; direction: "ascending" | "descending" };
  stickyHeader?: boolean;
  /** Shown when there are no rows. */
  empty?: ReactNode;
  className?: string;
};

const compare = (a: unknown, b: unknown) => {
  if (a == null && b == null) return 0;
  if (a == null) return 1;
  if (b == null) return -1;
  if (typeof a === "number" && typeof b === "number") return a - b;
  if (a instanceof Date && b instanceof Date) return a.getTime() - b.getTime();
  if (typeof a === "boolean" && typeof b === "boolean") return Number(a) - Number(b);
  return String(a).localeCompare(String(b), undefined, { numeric: true, sensitivity: "base" });
};

/**
 * A complete data table from the library's parts: click a header to sort (ascending, descending, off), select rows with
 * checkboxes (a header checkbox selects the page), and page through with `Pagination`. Rows, columns and selection are
 * plain props; selection can be controlled.
 */
export function DataTable<T>({
  caption,
  columns,
  rows,
  getRowId,
  selectable,
  selected,
  defaultSelected,
  onSelectedChange,
  pageSize,
  defaultSort,
  stickyHeader,
  empty = "Nothing to show.",
  className,
}: DataTableProps<T>) {
  const [sort, setSort] = useState<{ id: string; direction: "ascending" | "descending" } | undefined>(defaultSort);
  const [page, setPage] = useState(1);
  const [ids, setIds] = useControllableState<string[]>({
    value: selected,
    defaultValue: defaultSelected ?? [],
    onChange: onSelectedChange,
  });
  const chosen = useMemo(() => new Set(ids), [ids]);

  const sorted = useMemo(() => {
    const col = sort && columns.find((c) => c.id === sort.id);
    if (!col?.accessor) return rows;
    const get = col.accessor;
    const dir = sort?.direction === "descending" ? -1 : 1;
    return [...rows].sort((a, b) => dir * compare(get(a), get(b)));
  }, [rows, columns, sort]);

  const pages = pageSize ? Math.max(1, Math.ceil(sorted.length / pageSize)) : 1;
  const current = Math.min(page, pages);
  const visible = pageSize ? sorted.slice((current - 1) * pageSize, current * pageSize) : sorted;
  const visibleIds = visible.map(getRowId);
  const allOnPage = visibleIds.length > 0 && visibleIds.every((id) => chosen.has(id));
  const someOnPage = visibleIds.some((id) => chosen.has(id));

  // hover highlight with a soft falloff: the row under the pointer lights most, its neighbors a little
  const tableBox = useRef<HTMLDivElement>(null);
  useProximity(tableBox, {
    itemSelector: "tbody > tr",
    axis: "y",
    hit: "self",
    bounded: true,
    reach: 58,
    restBase: 0,
    restSpread: 0,
    peak: 1,
    smoothing: 0.22,
  });
  const headCheck = useRef<HTMLInputElement>(null);
  useEffect(() => {
    if (headCheck.current) headCheck.current.indeterminate = someOnPage && !allOnPage;
  }, [someOnPage, allOnPage]);

  const toggleRow = (id: string) => setIds(chosen.has(id) ? ids.filter((x) => x !== id) : [...ids, id]);
  const togglePage = () =>
    setIds(allOnPage ? ids.filter((id) => !visibleIds.includes(id)) : [...new Set([...ids, ...visibleIds])]);
  const cycle = (id: string) =>
    setSort((s) =>
      s?.id !== id
        ? { id, direction: "ascending" }
        : s.direction === "ascending"
          ? { id, direction: "descending" }
          : undefined,
    );

  return (
    <div className={cx("hm-datatable", className)} ref={tableBox}>
      <Table stickyHeader={stickyHeader} containerLabel={caption} aria-label={caption} data-proximity="">
        <TableHeader>
          <TableRow>
            {selectable ? (
              <TableHead className="hm-datatable-check">
                <Checkbox
                  ref={headCheck}
                  label={<span className="hm-sr-only">Select all rows on this page</span>}
                  checked={allOnPage}
                  onChange={togglePage}
                />
              </TableHead>
            ) : null}
            {columns.map((c) => (
              <TableHead
                key={c.id}
                align={c.numeric ? "end" : "start"}
                sort={c.sortable ? (sort?.id === c.id ? sort.direction : "none") : undefined}
                onSort={c.sortable && c.accessor ? () => cycle(c.id) : undefined}
              >
                {c.header}
              </TableHead>
            ))}
          </TableRow>
        </TableHeader>
        <TableBody key={`${current}-${sort?.id}-${sort?.direction}`}>
          {visible.length === 0 ? (
            <TableRow>
              <TableCell colSpan={columns.length + (selectable ? 1 : 0)} className="hm-datatable-empty">
                {empty}
              </TableCell>
            </TableRow>
          ) : (
            visible.map((row, index) => {
              const id = getRowId(row);
              return (
                <TableRow key={id} selected={chosen.has(id)} style={{ "--hm-i": index } as CSSProperties}>
                  {selectable ? (
                    <TableCell className="hm-datatable-check">
                      <Checkbox
                        label={<span className="hm-sr-only">Select row</span>}
                        checked={chosen.has(id)}
                        onChange={() => toggleRow(id)}
                      />
                    </TableCell>
                  ) : null}
                  {columns.map((c) => (
                    <TableCell key={c.id} numeric={c.numeric} rowHeader={c.rowHeader}>
                      {c.cell ? c.cell(row) : (c.accessor?.(row) as ReactNode)}
                    </TableCell>
                  ))}
                </TableRow>
              );
            })
          )}
        </TableBody>
      </Table>
      {pageSize && sorted.length > pageSize ? (
        <div className="hm-datatable-foot">
          <span className="hm-datatable-count" aria-live="polite">
            {(current - 1) * pageSize + 1}–{Math.min(current * pageSize, sorted.length)} of {sorted.length}
            {selectable && ids.length ? `, ${ids.length} selected` : ""}
          </span>
          <Pagination page={current} pageCount={pages} onPageChange={setPage} aria-label={`${caption} pages`} />
        </div>
      ) : selectable && ids.length ? (
        <p className="hm-datatable-count" aria-live="polite">
          {ids.length} selected
        </p>
      ) : null}
    </div>
  );
}
